#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  COLORREF l,d,f;  int nCount;  } Queue_GradRC;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static void FillSolidRect(HDC hDC,int x, int y, int cx, int cy, COLORREF clr)  {  ::SetBkColor(hDC, clr);  RECT rect = {x, y, x + cx, y + cy};  ::ExtTextOut(hDC, 0, 0, ETO_OPAQUE, &rect, NULL, 0, NULL);  }static void Draw3dRect(HDC hDC,int x, int y, int cx, int cy,	COLORREF clrTopLeft, COLORREF clrBottomRight)  {  FillSolidRect(hDC,x     , y     , cx - 1,      1, clrTopLeft);  FillSolidRect(hDC,x     , y     ,      1, cy - 1, clrTopLeft);  FillSolidRect(hDC,x + cx, y     ,     -1, cy    , clrBottomRight);  FillSolidRect(hDC,x     , y + cy, cx    ,     -1, clrBottomRight);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintGradRC(DefinePaint)  {  QueueP(Queue_GradRC);  COLORREF tl = p->f;  COLORREF br = p->f;  CMyBrush brush( hDC, p->f );  brush.Rect( p->mRect );  COLORREF color = ::SetBkColor(hDC, 0);  RECT rect = p->mRect;  for ( int n = 0; n < p->nCount; n++ )    {    ::InflateRect( &rect, 1, 1 );    tl += 0x0f0f0f;    br -= 0x0f0f0f;    Draw3dRect( hDC, rect.left, rect.top,      rect.right - rect.left,      rect.bottom - rect.top, tl, br);    }  ::SetBkColor( hDC, color );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddGradRC(DefineTegs)  {  RECT rect;  if ( !ParserRect(teg[0].value,rect) ) return;  //  AddQueueEx(Queue_GradRC);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintGradRC;  p->mRect = rect;  p->l = 0xffffff;  p->d = 0x000000;  p->f = 0x808080;  p->nCount = 8;  //  STegObj obj[] =    {    { 'A', "light", &p->l      },    { 'A', "dark" , &p->d      },    { 'A', "fon"  , &p->f      },    { 'I', "count", &p->nCount },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~